// Italian plural / gender folding: try the singular masculine/feminine/-e/-io/-ia variants of the normalised word.
const forms = w => {
  const o = new Set();
  if (w.length < 4) return [];
  const l = w[w.length - 1], b = w.slice(0, -1);
  if ("aeio".includes(l)) {
    for (const v of "aeio") if (v !== l) o.add(b + v);
    if (l === "i") { o.add(b + "io"); o.add(b + "ia"); }
    if (l === "e") { o.add(b + "ia"); o.add(b + "io"); }
    if (w.endsWith("che")) o.add(w.slice(0, -3) + "ca");
    if (w.endsWith("ghe")) o.add(w.slice(0, -3) + "ga");
    if (w.endsWith("chi")) { o.add(w.slice(0, -3) + "co"); o.add(w.slice(0, -3) + "chio"); }
    if (w.endsWith("ghi")) o.add(w.slice(0, -3) + "go");
    if (w.endsWith("ie")) o.add(w.slice(0, -2) + "ia");
    if (w.endsWith("ici")) o.add(w.slice(0, -3) + "ico");
    if (w.endsWith("ori")) o.add(w.slice(0, -3) + "ore");
    if (w.endsWith("tori")) o.add(w.slice(0, -4) + "tore");
    if (w.endsWith("zioni")) o.add(w.slice(0, -5) + "zione");
  }
  o.delete(w);
  return [...o];
};

